 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {}
            for y, x in comp:
                colors.setdefault(grid[y][x], []).append((y,x))
            # Nested color regions form successive rectangular layers; order by
            # the bounding-box area of each color, from outside to inside.
            ordered = sorted(colors, key=lambda col: -((max(y for y,x in colors[col])-min(y for y,x in colors[col])+1) * (max(x for y,x in colors[col])-min(x for y,x in colors[col])+1)))
            remap = dict(zip(ordered, reversed(ordered)))
            for y, x in comp:
                out[y][x] = remap[grid[y][x]]
    return out

